/**
 * Snapshots written by the published 0.2.0 (`version: 1`) must keep restoring, and the restored guard
 * must give the verdicts and summaries that 0.2.0 itself gave.
 *
 * The files in `test/fixtures/` were generated by installing `@osama.ansar/agent-loopguard@0.2.0`
 * from npm into a scratch project, running the steps in `before`, taking `guard.toJSON()` (or
 * `guard.snapshot({ redact: true })`), then restoring that snapshot with 0.2.0 itself and recording what it
 * answered to the steps in `after` (`expected`). They are plain JSON and are not regenerated by the tests.
 */
import { readFileSync, readdirSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { createGuard, restoreGuard } from '../src/index';
import type { GuardOptions, GuardSnapshot, GuardStep, Verdict } from '../src/index';

interface Fixture {
  generatedBy: string;
  name: string;
  options: GuardOptions & { nowMs?: number };
  before: GuardStep[];
  snapshot: GuardSnapshot;
  after: GuardStep[];
  expected: { verdicts: Verdict[]; summaries: unknown[]; finalSnapshot: GuardSnapshot };
}

const DIR = new URL('./fixtures/', import.meta.url);
const files = readdirSync(DIR).filter((f) => f.startsWith('v1-') && f.endsWith('.json')).sort();
const fixtures: Fixture[] = files.map((f) => JSON.parse(readFileSync(new URL(f, DIR), 'utf8')) as Fixture);

function optionsOf(fixture: Fixture): GuardOptions {
  const { nowMs, ...rest } = fixture.options;
  return nowMs === undefined ? rest : { ...rest, now: () => nowMs };
}

/** Keys that 0.3.0 may add to a snapshot. Everything else must be exactly what 0.2.0 wrote. */
function withoutAdditions(snapshot: GuardSnapshot): unknown {
  const copy = structuredClone(snapshot) as unknown as Record<string, unknown>;
  delete copy['callsByTool'];
  return copy;
}

describe('compatibility: snapshots written by 0.2.0', () => {
  it('has fixtures from the published 0.2.0, all of them version 1', () => {
    expect(fixtures.length).toBeGreaterThanOrEqual(6);
    for (const fixture of fixtures) {
      expect(fixture.generatedBy).toBe('@osama.ansar/agent-loopguard@0.2.0');
      expect(fixture.snapshot.version).toBe(1);
    }
  });

  it.each(fixtures.map((f) => [f.name, f] as const))('%s: restores, and carries on exactly as 0.2.0 did', (_name, fixture) => {
    const restored = restoreGuard(fixture.snapshot, optionsOf(fixture));
    // Right after the restore, the new guard describes the same state in the same words.
    expect(withoutAdditions(restored.toJSON())).toEqual(fixture.snapshot);

    const verdicts: Verdict[] = [];
    const summaries: unknown[] = [];
    for (const s of fixture.after) {
      verdicts.push(restored.check(s));
      summaries.push({ ...restored.summary(), lastVerdict: null });
    }
    expect(verdicts).toEqual(fixture.expected.verdicts);
    expect(summaries).toEqual(fixture.expected.summaries);
    expect(withoutAdditions(restored.toJSON())).toEqual(fixture.expected.finalSnapshot);
  });

  it.each(fixtures.map((f) => [f.name, f] as const))('%s: the same continuation works through a structuredClone of the snapshot', (_name, fixture) => {
    const a = restoreGuard(structuredClone(fixture.snapshot), optionsOf(fixture));
    const b = restoreGuard(fixture.snapshot, optionsOf(fixture));
    for (const s of fixture.after) expect(a.check(s)).toEqual(b.check(s));
  });

  it.each(fixtures.map((f) => [f.name, f] as const))('%s: a fresh 0.3.0 guard fed the same steps writes the same snapshot', (_name, fixture) => {
    const fresh = createGuard(optionsOf(fixture));
    for (const s of fixture.before) fresh.check(s);
    if (fixture.snapshot.detectors.repeatedToolCall?.preview === '[redacted]') {
      expect(withoutAdditions(fresh.snapshot({ redact: true }))).toEqual(fixture.snapshot);
    } else {
      expect(withoutAdditions(fresh.toJSON())).toEqual(fixture.snapshot);
    }
  });

  it('refuses a 0.2.0 snapshot under options that turn on a 0.3.0 feature, naming the option group', () => {
    const fixture = fixtures.find((f) => f.name === 'repeat-run') as Fixture;
    const options = optionsOf(fixture);
    expect(() => restoreGuard(fixture.snapshot, { ...options, repeatedToolCall: { window: { size: 10, maxRepeats: 3 } } })).toThrow(
      /taken with different options \(repeatedToolCall\)/,
    );
  });
});
